ucs.kql:
let LookbackDays = 7d;
let GamaredonChildren = dynamic(["mshta.exe","wscript.exe","cscript.exe","powershell.exe"]);
let GamaredonParents  = dynamic(["winword.exe","excel.exe","powerpnt.exe","outlook.exe","explorer.exe","winrar.exe","7zfm.exe","7zg.exe"]);
let SuspectCmdRegex   = @"(?i)(https?://|telegra\.ph|t\.me/|workers\.dev|trycloudflare\.com|\.online\b|\.ru\b|\.space\b|\.fun\b|\.site\b|GetObject\(|XMLHTTP|MSXML2|WScript\.Shell)";
let SuspectHostRegex  = @"(?i)(telegra\.ph|t\.me/|workers\.dev|trycloudflare\.com|\.online$|\.ru$|\.space$|\.fun$|\.site$)";
let ProcSpawn =
    DeviceProcessEvents
    | where Timestamp > ago(LookbackDays)
    | where FileName in~ (GamaredonChildren)
    | where InitiatingProcessFileName in~ (GamaredonParents)
    | where AccountName !endswith "$"
    | where ProcessCommandLine matches regex SuspectCmdRegex
    | project Timestamp, DeviceId, DeviceName, AccountName, ChildProc=FileName,
              ParentProc=InitiatingProcessFileName, ParentCmd=InitiatingProcessCommandLine,
              ChildCmd=ProcessCommandLine, ProcessId, SHA256;
let Egress =
    DeviceNetworkEvents
    | where Timestamp > ago(LookbackDays)
    | where RemoteIPType == "Public"
    | where InitiatingProcessFileName in~ (GamaredonChildren)
    | where RemoteUrl matches regex SuspectHostRegex or isnotempty(RemoteUrl)
    | project NetTime=Timestamp, DeviceId, InitiatingProcessId, RemoteUrl, RemoteIP, RemotePort;
ProcSpawn
| join kind=leftouter Egress on DeviceId, $left.ProcessId == $right.InitiatingProcessId
| where isnotempty(RemoteUrl) or ChildCmd matches regex @"(?i)(https?://|telegra\.ph|t\.me/|workers\.dev|trycloudflare)"
| project Timestamp, DeviceName, AccountName, ParentProc, ChildProc, ParentCmd, ChildCmd, RemoteUrl, RemoteIP, RemotePort, SHA256
| order by Timestamp desc

let LookbackDays = 7d;
let RemovableDriveCmd = @"(?i)\b[D-Z]:\\.*\.(vbs|vbe|js|jse|hta|cmd|bat|wsf|lnk|ps1)\b";
let ScriptChildren = dynamic(["wscript.exe","cscript.exe","mshta.exe","cmd.exe","powershell.exe"]);
let ProcSpawn =
    DeviceProcessEvents
    | where Timestamp > ago(LookbackDays)
    | where InitiatingProcessFileName =~ "explorer.exe"
    | where FileName in~ (ScriptChildren)
    | where AccountName !endswith "$"
    | where ProcessCommandLine matches regex RemovableDriveCmd
    | project Timestamp, DeviceId, DeviceName, AccountName, FileName, ProcessCommandLine, ProcessId, SHA256;
let UsbLnk =
    DeviceFileEvents
    | where Timestamp > ago(LookbackDays)
    | where ActionType in ("FileCreated","FileModified","FileRenamed")
    | where FileName endswith ".lnk"
    | where FolderPath matches regex @"(?i)^[D-Z]:\\"
    | project LnkTime=Timestamp, DeviceId, LnkPath=FolderPath, LnkName=FileName, LnkSHA256=SHA256, LnkWriter=InitiatingProcessFileName;
ProcSpawn
| join kind=leftouter UsbLnk on DeviceId
| where isnull(LnkTime) or (Timestamp between (LnkTime - 5m .. LnkTime + 1h))
| project Timestamp, DeviceName, AccountName, FileName, ProcessCommandLine, LnkName, LnkPath, LnkSHA256, LnkWriter, SHA256
| order by Timestamp desc
